  "concept_id": "ww-00028",
  "identity": {
    "name": "Hearthstone Law",
    "tagline": "Your legacy, carefully crafted.",
    "one_line_description": "Hearthstone Law is a boutique estate planning practice that helps families and individuals protect their assets, honor their wishes, and secure their loved ones' futures through thoughtful, personalized legal counsel.",
    "domain": "legal_professional",
    "subdomain": "estate planning practice",
    "voice": [
      "warm",
      "authoritative",
      "trustworthy",
      "precise"
    ],
    "target_audience": "Adults aged 35\u201370 who are building wealth, raising families, or approaching retirement and want professional guidance to create wills, trusts, powers of attorney, and comprehensive estate plans."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Immediately establish trust and warmth, communicate the firm's core value proposition in estate planning, and guide visitors toward booking a consultation or exploring services.",
      "meta_description": "Hearthstone Law helps families protect what matters most through expert estate planning, wills, trusts, and powers of attorney. Schedule your consultation today.",
      "sections": [
        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Capture attention and emotionally connect with visitors by speaking directly to the desire to protect family and legacy, while establishing Hearthstone Law as a trusted, established firm.",
          "eyebrow": "Estate Planning Attorneys",
          "headline": "Protect What You've Built. Provide for Those You Love.",
          "subheadline": "Hearthstone Law crafts personalized estate plans that honor your wishes, safeguard your assets, and give your family lasting peace of mind.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Schedule a Free Consultation",
              "target_page": "book"
            },
            {
              "label": "Explore Our Services",
              "target_page": "services"
            }
          ],
          "asset_ideas": [
            {
              "id": "home-section-1-asset-1",
              "kind": "illustration",
              "subject": "A stylized house with a protective shield and document scroll, rendered in a tactile skeuomorphic style suggesting permanence and care.",
              "purpose": "Anchor the hero visually with a warm, trustworthy symbol that bridges home, protection, and legal documentation.",
              "quantity": 1,
              "used_by": [
                "home-section-1"
              ]
            }
          ]
        },
        {
          "id": "home-section-2",
          "type": "feature_grid",
          "intent": "Quickly orient visitors to the firm's key practice areas so they can self-identify their need and feel confident the firm handles their situation.",
          "eyebrow": "What We Do",
          "headline": "Comprehensive Estate Planning Under One Roof",
          "subheadline": "From simple wills to complex trust structures, we guide you through every step.",
          "body": null,
          "items": [
            {
              "title": "Wills & Testaments",
              "description": "Clearly document your wishes for asset distribution, guardianship of minor children, and final arrangements.",
              "metadata": {}
            },
            {
              "title": "Revocable Living Trusts",
              "description": "Avoid probate, maintain privacy, and ensure seamless transfer of your estate to your beneficiaries.",
              "metadata": {}
            },
            {
              "title": "Powers of Attorney",
              "description": "Designate trusted individuals to manage your financial and medical decisions if you become incapacitated.",
              "metadata": {}
            },
            {
              "title": "Healthcare Directives",
              "description": "Articulate your medical preferences in advance so your family never faces impossible decisions alone.",
              "metadata": {}
            }
          ],
          "ctas": [
            {
              "label": "See All Services",
              "target_page": "services"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "home-section-3",
          "type": "testimonial",
          "intent": "Build social proof and emotional resonance by showing real client experiences, reinforcing that Hearthstone Law delivers both legal expertise and genuine human care.",
          "eyebrow": "Client Stories",
          "headline": "Families Who Found Peace of Mind",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Margaret & Thomas R., Retired Educators",
              "description": "\"We put off estate planning for years because it felt overwhelming. Hearthstone made the entire process feel manageable and even meaningful. Our children now have a clear roadmap.\"",
              "metadata": {}
            },
            {
              "title": "David K., Small Business Owner",
              "description": "\"I needed a plan that protected both my business and my family. The team at Hearthstone understood the complexity and delivered a trust structure that gave me complete confidence.\"",
              "metadata": {}
            },
            {
              "title": "Sandra L., Single Parent",
              "description": "\"As a single mom, making sure my kids are cared for if something happens to me was everything. Hearthstone guided me with patience and real expertise.\"",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "home-section-4",
          "type": "cta",
          "intent": "Convert warmed-up visitors into booked consultations with a direct, low-friction invitation that reinforces the firm's approachability.",
          "eyebrow": "Take the First Step",
          "headline": "Your Estate Plan Starts with a Conversation",
          "subheadline": "Schedule a complimentary 30-minute consultation and discover exactly what your family needs to be protected.",
          "body": null,
