              "target_page": "book"
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "about",
      "title": "About",
      "role": "editorial",
      "goal": "Humanize the firm by telling the story of its founding philosophy, the attorneys behind it, and the values that guide every client relationship, building deep trust before a visitor commits to working with the firm.",
      "meta_description": "Meet the Hearthstone Law team \u2014 experienced estate planning attorneys dedicated to helping families protect their legacies with care, clarity, and integrity.",
      "sections": [
        {
          "id": "about-section-1",
          "type": "page_header",
          "intent": "Set the tone for the About page by framing the firm's identity around people and purpose rather than credentials alone.",
          "eyebrow": "Our Story",
          "headline": "Built on the Belief That Every Family Deserves a Plan",
          "subheadline": "Hearthstone Law was founded on the conviction that estate planning is one of the most profound acts of love a person can undertake.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "about-section-2",
          "type": "story_block",
          "intent": "Tell the firm's founding narrative in a compelling, personal way that distinguishes Hearthstone from transactional legal practices and creates emotional alignment with the visitor.",
          "eyebrow": "Why We Do This Work",
          "headline": "A Practice Born from Personal Experience",
          "subheadline": null,
          "body": "Founding attorney Eleanor Marsh began her career at a large regional firm, where she watched families navigate the chaos of losing a loved one without a plan in place. She saw estates tied up in probate for years, sibling relationships fractured over ambiguous wills, and grieving spouses left without access to basic funds. In 2009, she opened Hearthstone Law with a singular mission: to make thoughtful, thorough estate planning accessible to every family \u2014 not just the wealthy few. Today, the firm has helped over 1,400 families across the region put plans in place they can trust.",
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "about-section-2-asset-1",
              "kind": "illustration",
              "subject": "A stylized timeline ribbon showing key milestones of a law firm's growth, rendered with a skeuomorphic document-and-seal aesthetic.",
              "purpose": "Visually reinforce the firm's history and longevity alongside the founding narrative.",
              "quantity": 1,
              "used_by": [
                "about-section-2"
              ]
            }
          ]
        },
        {
          "id": "about-section-3",
          "type": "item_grid",
          "intent": "Introduce the attorneys and key staff so visitors can put faces and expertise to the firm, building personal connection and confidence in the team.",
          "eyebrow": "The Team",
          "headline": "Attorneys Who Listen First, Then Plan",
          "subheadline": "Our attorneys combine deep legal expertise with a genuine commitment to understanding each client's unique family situation.",
          "body": null,
          "items": [
            {
              "title": "Eleanor Marsh, J.D., LL.M.",
              "description": "Founding attorney and estate planning specialist with 20+ years of experience. Eleanor earned her LL.M. in Taxation from Georgetown and has been recognized as a Top Estate Planning Attorney by the State Bar Association for six consecutive years.",
              "metadata": {
                "role": "Founding Attorney"
              }
            },
            {
              "title": "James Okafor, J.D.",
              "description": "James focuses on trust administration, business succession planning, and high-net-worth estate strategies. He brings 12 years of experience and a reputation for making complex structures easy to understand.",
              "metadata": {
                "role": "Senior Associate"
              }
            },
            {
              "title": "Priya Nair, J.D.",
              "description": "Priya specializes in blended family estate planning, special needs trusts, and Medicaid planning. She is known for her empathetic approach and meticulous attention to detail.",
              "metadata": {
                "role": "Associate Attorney"
              }
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "about-section-4",
          "type": "feature_grid",
          "intent": "Articulate the firm's core values in a tangible, specific way that differentiates Hearthstone from competitors and gives visitors a clear sense of what working with the firm feels like.",
          "eyebrow": "Our Values",
          "headline": "The Principles That Guide Every Plan We Write",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Clarity Over Complexity",
              "description": "We translate legal language into plain English so you always understand exactly what your documents say and why.",
              "metadata": {}
