            {
              "title": "Plans That Fit Your Life",
              "description": "No templates. Every estate plan is built around your specific family, assets, and intentions.",
              "metadata": {}
            },
            {
              "title": "Relationships, Not Transactions",
              "description": "We maintain long-term relationships with clients, updating plans as life changes so your estate plan always reflects your current wishes.",
              "metadata": {}
