              "metadata": {
                "ideal_for": "Individuals, parents with minor children"
              }
            },
            {
              "title": "Revocable Living Trust",
              "description": "A flexible trust that holds your assets during your lifetime and transfers them to beneficiaries without probate. Maintains privacy and allows you to retain full control while you are living.",
              "metadata": {
                "ideal_for": "Homeowners, those with significant assets, blended families"
              }
            },
            {
              "title": "Durable Power of Attorney",
              "description": "Designates a trusted agent to manage your financial affairs \u2014 paying bills, managing investments, filing taxes \u2014 if you become unable to do so yourself.",
