            },
            {
              "title": "Special Needs Trust",
              "description": "Provides for a family member with disabilities without disqualifying them from government benefits such as Medicaid or SSI. Carefully structured to supplement, not replace, public assistance.",
              "metadata": {
                "ideal_for": "Families with a disabled child or dependent"
              }
