  justify-content: space-between;
  align-items: center;
  font-family: var(--font-accent);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--pewter);
}

/* -------------------------------------------------------------------------
   Responsive
   ------------------------------------------------------------------------- */
@media (max-width: 1024px) {
  .hero-watermark { font-size: 130px; right: -60px; }
  .hero-headline { font-size: 44px; }
  .hero .container,
  .services-header .container,
  .articles-header .container,
  .book-header .container,
  .contact-block .container {
    grid-template-columns: 1fr;
  }
  .contact-block .container { gap: 32px; }
  .story-block .container,
  .process-section {
    grid-template-columns: 1fr;
  }
  .story-illustration-card { transform: none; max-width: 480px; margin: 0 auto; }
  .story-pullquote { font-size: 44px; }
  .process-left { padding: 56px 32px; min-height: 280px; }
  .process-right { padding: 56px 32px; }
